'use client';

import { useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { Activity, Ban, Calculator, Check, ChevronRight, CircleDollarSign, Clock3, Download, FileDown, History, LayoutDashboard, Menu, Moon, Package, Pencil, Plus, Receipt, Search, Settings, ShieldCheck, Sparkles, Stethoscope, Sun, Trash2, TrendingUp, UserRound, X } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { DEFAULT_BRANDING, DEFAULT_MATERIALS, DEFAULT_PROCEDURES, DEFAULT_SETTINGS, FIXED_COST_CATEGORIES, MATERIAL_CATEGORIES, MATERIAL_UNITS, calculatePrice, formatCurrency, formatDate, getMonthlyFixedCosts, normalizeMaterial, normalizeProcedure, normalizeSettings, normalizeText, safeNumber, type BrandingSettings, type FixedCost, type HistoryEntry, type Material, type Procedure, type PricingSettings, type Quote, type QuoteItem } from '@/lib/pricing';

type View = 'dashboard' | 'simulator' | 'procedures' | 'materials' | 'fixed-costs' | 'budget' | 'settings' | 'history';
const STORAGE = { procedures: 'odontoprice-procedures', materials: 'odontoprice-materials', settings: 'odontoprice-settings', history: 'odontoprice-history', quotes: 'odontoprice-quotes' };
const newId = (prefix: string) => prefix + '-' + Date.now() + '-' + Math.random().toString(16).slice(2);
const dateInput = (value: string) => { const date = new Date(value); return Number.isNaN(date.getTime()) ? new Date().toISOString().slice(0, 10) : date.toISOString().slice(0, 10); };
function readStorage<T>(key: string, fallback: T): T { if (typeof window === 'undefined') return fallback; try { const value = window.localStorage.getItem(key); return value ? JSON.parse(value) as T : fallback; } catch { return fallback; } }

function Icon({ name }: { name: View }) {
  const props = { size: 18, strokeWidth: 1.8 };
  if (name === 'dashboard') return <LayoutDashboard {...props} />;
  if (name === 'simulator') return <Calculator {...props} />;
  if (name === 'procedures') return <Stethoscope {...props} />;
  if (name === 'materials') return <Package {...props} />;
  if (name === 'fixed-costs') return <Receipt {...props} />;
  if (name === 'budget') return <FileDown {...props} />;
  if (name === 'settings') return <Settings {...props} />;
  return <History {...props} />;
}

function Empty({ icon, title, description, action }: { icon: ReactNode; title: string; description: string; action?: ReactNode }) {
  return <div className="empty-state"><div className="empty-icon">{icon}</div><strong>{title}</strong><p>{description}</p>{action}</div>;
}
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="field-label"><span>{label}</span>{children}{hint && <small className="field-hint">{hint}</small>}</label>;
}
function Metric({ icon, tone, label, value, helper }: { icon: ReactNode; tone: string; label: string; value: string; helper: string }) {
  return <Card className="metric-card"><CardContent className="p-4"><div className={'metric-icon ' + tone}>{icon}</div><div className="metric-label">{label}</div><div className="metric-value">{value}</div><div className="metric-helper">{helper}</div></CardContent></Card>;
}
function Modal({ title, description, onClose, children, wide }: { title: string; description: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  return <dialog open className="modal-backdrop"><div className={'modal-card ' + (wide ? 'modal-wide' : '')}><div className="modal-header"><div><h2 id="modal-title">{title}</h2><p>{description}</p></div><Button variant="ghost" size="icon" onClick={onClose} aria-label="Fechar janela" title="Fechar"><X size={17} /></Button></div>{children}</div></dialog>;
}

function MaterialForm({ value, onClose, onSave }: { value: Material | 'new'; onClose: () => void; onSave: (material: Material) => void }) {
  const initial = value === 'new' ? { id: 'new-material', name: '', category: '', purchaseUnit: 'unidade', packageQuantity: 1, consumptionUnit: 'unidade', packagePrice: 0, baseUnitCost: 0, supplier: '', updatedAt: new Date().toISOString(), active: true, priceHistory: [] } : value;
  const [draft, setDraft] = useState<Material>(initial);
  const [error, setError] = useState('');
  const saving = useRef(false);
  const base = draft.packageQuantity > 0 ? draft.packagePrice / draft.packageQuantity : 0;
  const submit = (event: { preventDefault: () => void }) => { event.preventDefault(); if (saving.current) return; const price = safeNumber(draft.packagePrice, NaN); const quantity = safeNumber(draft.packageQuantity, NaN); if (!draft.name.trim()) return setError('Informe o nome do material.'); if (!draft.category) return setError('Selecione uma categoria.'); if (!Number.isFinite(quantity) || quantity <= 0) return setError('A quantidade deve ser maior que zero.'); if (!Number.isFinite(price) || price < 0) return setError('O preço deve ser válido e maior ou igual a zero.'); saving.current = true; onSave({ ...draft, name: draft.name.trim(), packageQuantity: quantity, packagePrice: price, baseUnitCost: price / quantity }); };
  return <Modal title={value === 'new' ? 'Novo material' : 'Editar material'} description="Informe compra e consumo para calcular o custo base." onClose={onClose} wide><form className="modal-form" onSubmit={submit}><div className="field-grid"><Field label="Nome *"><Input value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="Ex.: Resina composta A1" /></Field><Field label="Categoria *"><select className="select-input" value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })}><option value="">Selecione</option>{MATERIAL_CATEGORIES.map((item) => <option key={item}>{item}</option>)}</select></Field></div><div className="field-grid"><Field label="Unidade de compra *"><select className="select-input" value={draft.purchaseUnit} onChange={(e) => setDraft({ ...draft, purchaseUnit: e.target.value })}>{MATERIAL_UNITS.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Quantidade da embalagem *"><Input type="number" min="0.000001" step="any" value={draft.packageQuantity} onChange={(e) => setDraft({ ...draft, packageQuantity: Number(e.target.value) })} /></Field></div><div className="field-grid"><Field label="Unidade de consumo *"><select className="select-input" value={draft.consumptionUnit} onChange={(e) => setDraft({ ...draft, consumptionUnit: e.target.value })}>{MATERIAL_UNITS.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Preço da embalagem *"><div className="input-suffix"><span>R$</span><Input type="number" min="0" step="0.01" value={draft.packagePrice} onChange={(e) => setDraft({ ...draft, packagePrice: Number(e.target.value) })} /></div></Field></div><div className="base-cost-callout"><div><span>Custo por unidade base</span><strong>{formatCurrency(Number.isFinite(base) ? base : 0)}</strong></div><small>Preço da embalagem ÷ quantidade da embalagem.</small></div><div className="field-grid"><Field label="Fornecedor (opcional)"><Input value={draft.supplier} onChange={(e) => setDraft({ ...draft, supplier: e.target.value })} placeholder="Ex.: Dental Supply" /></Field><Field label="Data da atualização"><Input type="date" value={dateInput(draft.updatedAt)} onChange={(e) => setDraft({ ...draft, updatedAt: new Date(e.target.value + 'T12:00:00').toISOString() })} /></Field></div><label className="switch-row"><input type="checkbox" checked={draft.active} onChange={(e) => setDraft({ ...draft, active: e.target.checked })} /><span>Material ativo para novos procedimentos</span></label>{value !== 'new' && draft.priceHistory.length > 0 && <div className="price-history-box"><strong>Histórico de preços</strong>{draft.priceHistory.slice().reverse().map((item) => <div key={item.id}><span>{formatDate(item.updatedAt)} · {item.supplier || 'Fornecedor não informado'}</span><span>{formatCurrency(item.previousPackagePrice)} → {formatCurrency(item.newPackagePrice)}</span></div>)}</div>}{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><Button type="button" variant="outline" onClick={onClose}>Cancelar</Button><Button type="submit" className="primary-button"><Check size={15} /> Salvar material</Button></div></form></Modal>;
}

function ProcedureForm({ value, materials, onClose, onSave }: { value: Procedure | 'new'; materials: Material[]; onClose: () => void; onSave: (procedure: Procedure) => void }) {
  const initial = value === 'new' ? { id: newId('procedure'), name: '', category: '', durationMinutes: 60, otherVariableCost: 0, materials: [] } : value;
  const [draft, setDraft] = useState<Procedure>(initial);
  const [error, setError] = useState('');
  const toggle = (id: string, checked: boolean) => setDraft({ ...draft, materials: checked ? [...draft.materials, { materialId: id, quantity: 1 }] : draft.materials.filter((item) => item.materialId !== id) });
  const submit = (event: { preventDefault: () => void }) => { event.preventDefault(); if (!draft.name.trim() || !draft.category) return setError('Nome e categoria são obrigatórios.'); if (!Number.isFinite(draft.durationMinutes) || draft.durationMinutes <= 0) return setError('A duração deve ser maior que zero.'); onSave({ ...draft, name: draft.name.trim(), durationMinutes: Math.round(draft.durationMinutes), otherVariableCost: Math.max(0, safeNumber(draft.otherVariableCost)) }); };
  return <Modal title={value === 'new' ? 'Novo procedimento' : 'Editar procedimento'} description="Vincule os materiais consumidos no atendimento." onClose={onClose} wide><form className="modal-form" onSubmit={submit}><div className="field-grid"><Field label="Nome *"><Input value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} /></Field><Field label="Categoria *"><Input value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })} /></Field></div><div className="field-grid"><Field label="Tempo clínico (min) *"><Input type="number" min="1" value={draft.durationMinutes} onChange={(e) => setDraft({ ...draft, durationMinutes: Number(e.target.value) })} /></Field><Field label="Outros custos variáveis"><Input type="number" min="0" step="0.01" value={draft.otherVariableCost} onChange={(e) => setDraft({ ...draft, otherVariableCost: Number(e.target.value) })} /></Field></div><div className="material-picker"><p className="eyebrow">Materiais consumidos</p>{materials.length === 0 && <p className="field-hint">Cadastre materiais para vinculá-los ao procedimento.</p>}{materials.map((material) => { const selected = draft.materials.find((item) => item.materialId === material.id); return <div className="material-check" key={material.id}><label><input type="checkbox" checked={Boolean(selected)} onChange={(e) => toggle(material.id, e.target.checked)} />{material.name}{!material.active && <Badge variant="outline">Inativo</Badge>}</label>{selected && <span className="small-quantity"><Input type="number" min="0.001" step="any" value={selected.quantity} onChange={(e) => setDraft({ ...draft, materials: draft.materials.map((item) => item.materialId === material.id ? { ...item, quantity: Number(e.target.value) } : item) })} /> {material.consumptionUnit}</span>}<strong>{formatCurrency(material.baseUnitCost)}</strong></div>; })}</div>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><Button type="button" variant="outline" onClick={onClose}>Cancelar</Button><Button type="submit" className="primary-button"><Check size={15} /> Salvar procedimento</Button></div></form></Modal>;
}

function FixedCostForm({ value, onClose, onSave }: { value: FixedCost | 'new'; onClose: () => void; onSave: (cost: FixedCost) => void }) {
  const initial = value === 'new' ? { id: newId('fixed'), name: '', category: '', monthlyValue: 0, active: true } : value;
  const [draft, setDraft] = useState<FixedCost>(initial);
  const [error, setError] = useState('');
  const submit = () => { const amount = safeNumber(draft.monthlyValue, NaN); if (!draft.name.trim() || !draft.category) return setError('Nome e categoria são obrigatórios.'); if (!Number.isFinite(amount) || amount < 0) return setError('Informe um valor mensal válido.'); onSave({ ...draft, name: draft.name.trim(), monthlyValue: amount }); };
  return <Modal title={value === 'new' ? 'Novo custo fixo' : 'Editar custo fixo'} description="Discrimine despesas recorrentes da operação." onClose={onClose}><form className="modal-form" onSubmit={(e) => { e.preventDefault(); submit(); }}><div className="field-grid"><Field label="Descrição *"><Input value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="Ex.: aluguel" /></Field><Field label="Categoria *"><select className="select-input" value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })}><option value="">Selecione</option>{FIXED_COST_CATEGORIES.map((item) => <option key={item}>{item}</option>)}</select></Field></div><Field label="Valor mensal *"><Input type="number" min="0" step="0.01" value={draft.monthlyValue} onChange={(e) => setDraft({ ...draft, monthlyValue: Number(e.target.value) })} /></Field><label className="switch-row"><input type="checkbox" checked={draft.active} onChange={(e) => setDraft({ ...draft, active: e.target.checked })} /><span>Considerar nos cálculos</span></label>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><Button type="button" variant="outline" onClick={onClose}>Cancelar</Button><Button type="submit" className="primary-button"><Check size={15} /> Salvar custo</Button></div></form></Modal>;
}

function Dashboard({ procedures, materials, settings, navigate }: { procedures: Procedure[]; materials: Material[]; settings: PricingSettings; navigate: (view: View) => void }) {
  const data = procedures.map((procedure) => ({ procedure, calculation: calculatePrice(procedure, settings, materials) })).sort((a, b) => b.calculation.recommendedPrice - a.calculation.recommendedPrice);
  const margin = data.length ? data.reduce((sum, item) => sum + item.calculation.profitMargin, 0) / data.length : 0;
  return <><div className="page-heading"><div><p className="eyebrow">VISÃO GERAL</p><h1>Olá, Dra. Fernanda <span className="wave">✦</span></h1><p className="page-description">Acompanhe a saúde financeira dos seus atendimentos.</p></div><Button className="primary-button" onClick={() => navigate('simulator')}><Calculator size={15} /> Simular preço</Button></div><div className="metrics-grid"><Metric icon={<CircleDollarSign size={17} />} tone="teal" label="Preço recomendado médio" value={formatCurrency(data.length ? data.reduce((sum, item) => sum + item.calculation.recommendedPrice, 0) / data.length : 0)} helper={procedures.length + ' procedimentos'} /><Metric icon={<TrendingUp size={17} />} tone="gold" label="Margem média" value={margin.toFixed(1) + '%'} helper="Após impostos e taxas" /><Metric icon={<Clock3 size={17} />} tone="blue" label="Custo da hora clínica" value={formatCurrency(getMonthlyFixedCosts(settings) / Math.max(settings.monthlyClinicalHours, 1))} helper={settings.monthlyClinicalHours + 'h produtivas/mês'} /><Metric icon={<Package size={17} />} tone="violet" label="Materiais ativos" value={String(materials.filter((item) => item.active).length)} helper={materials.length + ' cadastrados'} /></div><div className="dashboard-grid"><Card className="chart-card"><CardHeader className="section-card-header"><div><CardTitle>Preço recomendado por procedimento</CardTitle><p>Comparativo do catálogo atual</p></div><Badge className="live-badge"><Activity size={12} /> Atualizado agora</Badge></CardHeader><CardContent><div className="bar-chart">{data.length ? data.slice(0, 4).map(({ procedure, calculation }) => <div key={procedure.id}><div className="bar-label"><span>{procedure.name}</span><strong>{formatCurrency(calculation.recommendedPrice)}</strong></div><div className="bar-track"><div className="bar-fill" style={{ width: (data[0].calculation.recommendedPrice ? calculation.recommendedPrice / data[0].calculation.recommendedPrice * 100 : 0) + '%' }} /></div></div>) : <Empty icon={<Stethoscope size={18} />} title="Comece pelo seu catálogo" description="Cadastre um procedimento para visualizar os indicadores." action={<Button variant="outline" onClick={() => navigate('procedures')}>Cadastrar procedimento</Button>} />}</div></CardContent></Card><Card className="insight-card"><CardHeader><CardTitle><Sparkles size={16} /> Insight financeiro</CardTitle></CardHeader><CardContent><p>{data.length ? 'Sua margem média já considera custos fixos, materiais, impostos e taxas.' : 'Configure custos fixos e cadastre serviços para receber insights.'}</p><div className="insight-number">{margin.toFixed(1)}%</div><div className="insight-line"><span><TrendingUp size={13} /> Margem média</span><strong>{data.length ? 'calculada' : 'aguardando dados'}</strong></div><div className="insight-line"><span><Check size={13} /> Integridade</span><strong>Dados locais</strong></div><Button variant="ghost" className="full-button" onClick={() => navigate('settings')}>Revisar configurações <ChevronRight size={13} /></Button></CardContent></Card></div><div className="section-title-row"><div><p className="eyebrow">CATÁLOGO</p><h2>Procedimentos recentes</h2></div><Button variant="ghost" onClick={() => navigate('procedures')}>Ver todos <ChevronRight size={13} /></Button></div><Card className="table-card"><Table><TableHeader><TableRow><TableHead>Procedimento</TableHead><TableHead>Tempo</TableHead><TableHead>Custo real</TableHead><TableHead>Preço recomendado</TableHead><TableHead>Margem</TableHead></TableRow></TableHeader><TableBody>{data.slice(0, 5).map(({ procedure, calculation }) => <TableRow key={procedure.id}><TableCell><div className="procedure-cell"><div className="procedure-symbol">OD</div><div><strong>{procedure.name}</strong><span>{procedure.category}</span></div></div></TableCell><TableCell>{procedure.durationMinutes} min</TableCell><TableCell>{formatCurrency(calculation.realCost)}</TableCell><TableCell><strong>{formatCurrency(calculation.recommendedPrice)}</strong></TableCell><TableCell><Badge className="soft-success">{calculation.profitMargin.toFixed(1)}%</Badge></TableCell></TableRow>)}</TableBody></Table>{!procedures.length && <Empty icon={<Stethoscope size={18} />} title="Nenhum procedimento cadastrado" description="Adicione seus próprios serviços para começar." action={<Button className="primary-button" onClick={() => navigate('procedures')}><Plus size={15} /> Novo procedimento</Button>} />}</Card></>;
}

function Simulator({ procedures, materials, settings }: { procedures: Procedure[]; materials: Material[]; settings: PricingSettings }) {
  const [selected, setSelected] = useState(procedures[0]?.id || '');
  const [discount, setDiscount] = useState(0);
  const [margin, setMargin] = useState<number | ''>('');
  const procedure = procedures.find((item) => item.id === selected) || procedures[0];
  const calc = procedure ? calculatePrice(procedure, settings, materials, discount, margin === '' ? undefined : Number(margin)) : null;
  return <><div className="page-heading"><div><p className="eyebrow">PRECIFICAÇÃO</p><h1>Simulador de preços</h1><p className="page-description">Teste cenários sem alterar seu catálogo.</p></div><Badge className="live-badge"><Activity size={12} /> Cálculo em tempo real</Badge></div>{!procedure ? <Card className="table-card"><Empty icon={<Calculator size={18} />} title="Cadastre um procedimento primeiro" description="O simulador usa seus serviços, materiais e custos reais." /></Card> : <div className="simulator-grid"><Card className="simulator-controls"><CardHeader><CardTitle>Parâmetros do cenário</CardTitle><p>Ajuste desconto e margem.</p></CardHeader><CardContent><Field label="Procedimento"><select className="select-input" value={procedure.id} onChange={(e) => setSelected(e.target.value)}>{procedures.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><div className="field-grid"><Field label="Desconto aplicado"><Input type="number" min="0" max="100" value={discount} onChange={(e) => setDiscount(Number(e.target.value))} /></Field><Field label="Margem desejada"><Input type="number" min="0" value={margin} placeholder={String(settings.defaultMargin)} onChange={(e) => setMargin(e.target.value === '' ? '' : Number(e.target.value))} /></Field></div><div className="scenario-note"><ShieldCheck size={17} /><div><strong>Dados protegidos</strong><p>Esta simulação não muda seus cadastros.</p></div></div><div className="cost-list"><div><span>Materiais e variáveis</span><strong>{formatCurrency(calc?.variableCost || 0)}</strong></div><div><span>Rateio de custos fixos</span><strong>{formatCurrency(calc?.fixedAllocation || 0)}</strong></div></div></CardContent></Card><Card className="result-card"><div className="result-top"><div><p className="light-eyebrow">RESULTADO</p><h2>{procedure.name}</h2><p>{procedure.durationMinutes} minutos clínicos</p></div><div className="result-check"><Check size={16} /></div></div><div className="main-result"><span>Preço recomendado</span><strong>{formatCurrency(calc?.recommendedPrice || 0)}</strong><small>{discount ? 'Com ' + discount + '% de desconto: ' + formatCurrency(calc?.discountedPrice || 0) : 'Preço cheio do cenário'}</small></div><div className="result-mini-grid"><div><span>Custo real</span><strong>{formatCurrency(calc?.realCost || 0)}</strong></div><div><span>Preço mínimo</span><strong>{formatCurrency(calc?.minimumPrice || 0)}</strong></div><div><span>Lucro</span><strong className="result-profit">{formatCurrency(calc?.profit || 0)}</strong></div></div><div className="result-breakdown"><div><span>Impostos e taxas</span><strong>{formatCurrency(calc?.taxesAndFees || 0)}</strong></div><div><span>Margem efetiva</span><strong>{(calc?.profitMargin || 0).toFixed(1)}%</strong></div><div className="breakdown-total"><span>Total para cobrar</span><strong>{formatCurrency(calc?.discountedPrice || 0)}</strong></div></div><Button className="white-button" onClick={() => window.print()}>Imprimir simulação <Download size={14} /></Button></Card></div>}</>;
}

function Materials({ materials, onNew, onEdit, onInactivate, onActivate }: { materials: Material[]; onNew: () => void; onEdit: (material: Material) => void; onInactivate: (material: Material) => void; onActivate: (material: Material) => void }) {
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('all');
  const [status, setStatus] = useState('all');
  const [sort, setSort] = useState('name');
  const categories = Array.from(new Set(materials.map((item) => item.category))).sort();
  const filtered = useMemo(() => materials.filter((item) => { const term = normalizeText(search); return (!term || [item.name, item.category, item.purchaseUnit, item.consumptionUnit].some((field) => normalizeText(field).includes(term))) && (category === 'all' || item.category === category) && (status === 'all' || status === 'active' && item.active || status === 'inactive' && !item.active); }).sort((a, b) => sort === 'cost' ? b.baseUnitCost - a.baseUnitCost : sort === 'updated' ? new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime() : normalizeText(a.name).localeCompare(normalizeText(b.name))), [materials, search, category, status, sort]);
  const [now] = useState(() => new Date().getTime());
  const stale = materials.filter((item) => now - new Date(item.updatedAt).getTime() > 90 * 86400000).length;
  return <><div className="page-heading"><div><p className="eyebrow">INSUMOS</p><h1>Materiais e insumos</h1><p className="page-description">Custos de compra e consumo utilizados na precificação.</p></div><Button className="primary-button" onClick={onNew}><Plus size={15} /> Novo material</Button></div><div className="metrics-grid"><Metric icon={<Package size={17} />} tone="teal" label="Materiais cadastrados" value={String(materials.length)} helper="Registros preservados" /><Metric icon={<Check size={17} />} tone="gold" label="Materiais ativos" value={String(materials.filter((item) => item.active).length)} helper="Disponíveis para uso" /><Metric icon={<Clock3 size={17} />} tone="blue" label="Preços desatualizados" value={String(stale)} helper="Há mais de 90 dias" /><Metric icon={<Activity size={17} />} tone="violet" label="Categorias cadastradas" value={String(new Set(materials.map((item) => item.category)).size)} helper="Classificações usadas" /></div><Card className="table-card"><div className="table-toolbar materials-toolbar"><div className="search-box"><Search size={14} /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar nome, categoria ou unidade..." aria-label="Buscar materiais" /></div><div className="toolbar-filters"><select className="select-input compact-select" value={category} onChange={(e) => setCategory(e.target.value)} aria-label="Filtrar por categoria"><option value="all">Todas as categorias</option>{categories.map((item) => <option key={item}>{item}</option>)}</select><select className="select-input compact-select" value={status} onChange={(e) => setStatus(e.target.value)} aria-label="Filtrar por status"><option value="all">Todos os status</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select><select className="select-input compact-select" value={sort} onChange={(e) => setSort(e.target.value)} aria-label="Ordenar materiais"><option value="name">Ordenar: material</option><option value="cost">Ordenar: custo</option><option value="updated">Ordenar: atualização</option></select></div><span className="result-count">{filtered.length} resultado{filtered.length === 1 ? '' : 's'}</span></div><div className="desktop-materials-table"><Table><TableHeader><TableRow><TableHead>Material</TableHead><TableHead>Categoria</TableHead><TableHead>Unidade</TableHead><TableHead>Custo base</TableHead><TableHead>Última atualização</TableHead><TableHead className="text-right">Ações</TableHead></TableRow></TableHeader><TableBody>{filtered.map((material) => <TableRow key={material.id}><TableCell><div className="procedure-cell"><div className="material-symbol">IN</div><div><strong>{material.name}</strong><span>{material.supplier || 'Fornecedor não informado'}</span></div></div></TableCell><TableCell>{material.category}</TableCell><TableCell>{material.packageQuantity} {material.purchaseUnit} → {material.consumptionUnit}</TableCell><TableCell><strong>{formatCurrency(material.baseUnitCost)}</strong></TableCell><TableCell>{formatDate(material.updatedAt)}</TableCell><TableCell><div className="row-actions"><Button variant="ghost" size="icon" onClick={() => onEdit(material)} aria-label={'Editar ' + material.name} title="Editar material"><Pencil size={14} /></Button>{material.active ? <Button variant="ghost" size="icon" onClick={() => onInactivate(material)} aria-label={'Inativar ' + material.name} title="Inativar material"><Ban size={14} /></Button> : <Button variant="ghost" size="icon" onClick={() => onActivate(material)} aria-label={'Ativar ' + material.name} title="Ativar material"><Check size={14} /></Button>}</div></TableCell></TableRow>)}</TableBody></Table></div><div className="mobile-material-cards">{filtered.map((material) => <div className="material-mobile-card" key={material.id}><div className="material-mobile-head"><div><strong>{material.name}</strong><span>{material.category} · {material.active ? 'Ativo' : 'Inativo'}</span></div><strong>{formatCurrency(material.baseUnitCost)}</strong></div><div className="material-mobile-meta"><span>{material.packageQuantity} {material.purchaseUnit} → {material.consumptionUnit}</span><span>{formatDate(material.updatedAt)}</span></div><div className="row-actions"><Button variant="outline" size="sm" onClick={() => onEdit(material)} aria-label={'Editar ' + material.name} title="Editar material"><Pencil size={13} /> Editar</Button>{material.active ? <Button variant="outline" size="sm" onClick={() => onInactivate(material)} aria-label={'Inativar ' + material.name} title="Inativar material"><Ban size={13} /> Inativar</Button> : <Button variant="outline" size="sm" onClick={() => onActivate(material)} aria-label={'Ativar ' + material.name} title="Ativar material"><Check size={13} /> Ativar</Button>}</div></div>)}</div>{filtered.length === 0 && <Empty icon={<Package size={18} />} title={materials.length ? 'Nenhum resultado' : 'Nenhum material cadastrado'} description={materials.length ? 'Ajuste a busca ou os filtros.' : 'Cadastre o primeiro insumo para formar custos reais.'} action={!materials.length && <Button className="primary-button" onClick={onNew}><Plus size={15} /> Novo material</Button>} />}</Card></>;
}

function Procedures({ procedures, materials, settings, onNew, onEdit }: { procedures: Procedure[]; materials: Material[]; settings: PricingSettings; onNew: () => void; onEdit: (procedure: Procedure) => void }) {
  const [search, setSearch] = useState('');
  const filtered = procedures.filter((item) => normalizeText(item.name).includes(normalizeText(search)) || normalizeText(item.category).includes(normalizeText(search)));
  return <><div className="page-heading"><div><p className="eyebrow">CATÁLOGO</p><h1>Procedimentos</h1><p className="page-description">Serviços, tempos clínicos e materiais vinculados.</p></div><Button className="primary-button" onClick={onNew}><Plus size={15} /> Novo procedimento</Button></div><Card className="table-card"><div className="table-toolbar"><div className="search-box"><Search size={14} /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar procedimento..." /></div><span className="result-count">{filtered.length} resultado{filtered.length === 1 ? '' : 's'}</span></div><Table><TableHeader><TableRow><TableHead>Procedimento</TableHead><TableHead>Tempo</TableHead><TableHead>Materiais</TableHead><TableHead>Preço recomendado</TableHead><TableHead className="text-right">Ações</TableHead></TableRow></TableHeader><TableBody>{filtered.map((procedure) => { const calc = calculatePrice(procedure, settings, materials); return <TableRow key={procedure.id}><TableCell><div className="procedure-cell"><div className="procedure-symbol">OD</div><div><strong>{procedure.name}</strong><span>{procedure.category}</span></div></div></TableCell><TableCell>{procedure.durationMinutes} min</TableCell><TableCell>{procedure.materials.length} itens</TableCell><TableCell>{formatCurrency(calc.recommendedPrice)}</TableCell><TableCell><div className="row-actions"><Button variant="ghost" size="icon" onClick={() => onEdit(procedure)} aria-label={'Editar ' + procedure.name} title="Editar procedimento"><Pencil size={14} /></Button></div></TableCell></TableRow>; })}</TableBody></Table>{!filtered.length && <Empty icon={<Stethoscope size={18} />} title="Nenhum procedimento" description="Cadastre seus serviços para precificar atendimentos." action={<Button className="primary-button" onClick={onNew}><Plus size={15} /> Novo procedimento</Button>} />}</Card></>;
}

function FixedCosts({ settings, onSave, onHistory }: { settings: PricingSettings; onSave: (settings: PricingSettings) => void; onHistory: (action: string, detail: string) => void }) {
  const [modal, setModal] = useState<FixedCost | 'new' | null>(null);
  const costs = settings.fixedCosts || [];
  const save = (cost: FixedCost) => { const next = costs.some((item) => item.id === cost.id) ? costs.map((item) => item.id === cost.id ? cost : item) : [...costs, cost]; onSave(normalizeSettings({ ...settings, fixedCosts: next })); onHistory(costs.some((item) => item.id === cost.id) ? 'Custo fixo atualizado' : 'Custo fixo criado', cost.name); setModal(null); };
  const toggle = (cost: FixedCost) => { onSave(normalizeSettings({ ...settings, fixedCosts: costs.map((item) => item.id === cost.id ? { ...item, active: !item.active } : item) })); onHistory(cost.active ? 'Custo fixo desativado' : 'Custo fixo ativado', cost.name); };
  return <><div className="page-heading"><div><p className="eyebrow">ESTRUTURA DE CUSTOS</p><h1>Custos fixos detalhados</h1><p className="page-description">Discrimine despesas recorrentes e distribua o total pela hora clínica.</p></div><Button className="primary-button" onClick={() => setModal('new')}><Plus size={15} /> Novo custo fixo</Button></div><div className="metrics-grid metrics-grid-3"><Metric icon={<CircleDollarSign size={17} />} tone="teal" label="Total mensal ativo" value={formatCurrency(getMonthlyFixedCosts(settings))} helper="Considerado no cálculo" /><Metric icon={<Clock3 size={17} />} tone="blue" label="Custo por hora clínica" value={formatCurrency(getMonthlyFixedCosts(settings) / Math.max(settings.monthlyClinicalHours, 1))} helper={settings.monthlyClinicalHours + 'h/mês'} /><Metric icon={<Receipt size={17} />} tone="gold" label="Itens discriminados" value={String(costs.length)} helper={costs.filter((item) => item.active).length + ' ativos'} /></div><Card className="table-card"><Table><TableHeader><TableRow><TableHead>Descrição</TableHead><TableHead>Categoria</TableHead><TableHead>Valor mensal</TableHead><TableHead>Status</TableHead><TableHead className="text-right">Ações</TableHead></TableRow></TableHeader><TableBody>{costs.map((cost) => <TableRow key={cost.id}><TableCell><strong>{cost.name}</strong></TableCell><TableCell>{cost.category}</TableCell><TableCell>{formatCurrency(cost.monthlyValue)}</TableCell><TableCell><Badge variant={cost.active ? 'default' : 'outline'} className={cost.active ? 'soft-success' : ''}>{cost.active ? 'Ativo' : 'Inativo'}</Badge></TableCell><TableCell><div className="row-actions"><Button variant="ghost" size="icon" onClick={() => setModal(cost)} aria-label={'Editar ' + cost.name} title="Editar custo"><Pencil size={14} /></Button><Button variant="ghost" size="icon" onClick={() => toggle(cost)} aria-label={(cost.active ? 'Desativar ' : 'Ativar ') + cost.name} title={cost.active ? 'Desativar' : 'Ativar'}>{cost.active ? <Ban size={14} /> : <Check size={14} />}</Button></div></TableCell></TableRow>)}</TableBody></Table>{!costs.length && <Empty icon={<Receipt size={18} />} title="Nenhum custo fixo discriminado" description="Adicione aluguel, equipe, sistemas, contador e outras despesas." action={<Button className="primary-button" onClick={() => setModal('new')}><Plus size={15} /> Adicionar primeiro custo</Button>} />}</Card>{modal && <FixedCostForm value={modal} onClose={() => setModal(null)} onSave={save} />}</>;
}

function Budget({ procedures, materials, settings, quotes, onSave }: { procedures: Procedure[]; materials: Material[]; settings: PricingSettings; quotes: Quote[]; onSave: (quote: Quote) => void }) {
  const [client, setClient] = useState('');
  const [procedureId, setProcedureId] = useState(procedures[0]?.id || '');
  const [quantity, setQuantity] = useState(1);
  const [discount, setDiscount] = useState(0);
  const [items, setItems] = useState<QuoteItem[]>([]);
  const procedure = procedures.find((item) => item.id === procedureId);
  const add = () => { if (!procedure || quantity <= 0 || !Number.isFinite(quantity)) return; const price = calculatePrice(procedure, settings, materials).recommendedPrice; const existing = items.find((item) => item.procedureId === procedure.id); setItems(existing ? items.map((item) => item.procedureId === procedure.id ? { ...item, quantity: item.quantity + quantity } : item) : [...items, { id: newId('quote-item'), procedureId: procedure.id, procedureName: procedure.name, quantity, unitPrice: price }]); };
  const subtotal = items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);
  const total = subtotal * (1 - Math.min(100, Math.max(0, safeNumber(discount))) / 100);
  return <><div className="page-heading"><div><p className="eyebrow">ATENDIMENTO COMERCIAL</p><h1>Novo orçamento</h1><p className="page-description">Monte uma proposta usando os preços recomendados do catálogo.</p></div><Button variant="outline" onClick={() => window.print()}><Download size={15} /> Imprimir</Button></div><div className="budget-layout"><Card className="simulator-controls"><CardHeader><CardTitle>Serviços do orçamento</CardTitle><p>Adicione um ou mais procedimentos.</p></CardHeader><CardContent><Field label="Paciente ou cliente"><Input value={client} onChange={(e) => setClient(e.target.value)} placeholder="Opcional" /></Field><div className="budget-add-row"><Field label="Procedimento"><select className="select-input" value={procedureId} onChange={(e) => setProcedureId(e.target.value)}>{procedures.length ? procedures.map((item) => <option key={item.id} value={item.id}>{item.name}</option>) : <option value="">Nenhum procedimento cadastrado</option>}</select></Field><Field label="Qtd."><Input type="number" min="1" step="1" value={quantity} onChange={(e) => setQuantity(Number(e.target.value))} /></Field><Button className="primary-button budget-add-button" onClick={add} disabled={!procedure}><Plus size={15} /> Adicionar</Button></div><div className="quote-items">{items.length ? items.map((item) => <div className="quote-item" key={item.id}><div><strong>{item.procedureName}</strong><span>{item.quantity} × {formatCurrency(item.unitPrice)}</span></div><strong>{formatCurrency(item.quantity * item.unitPrice)}</strong><Button variant="ghost" size="icon" onClick={() => setItems(items.filter((current) => current.id !== item.id))} aria-label={'Remover ' + item.procedureName} title="Remover item"><Trash2 size={14} /></Button></div>) : <p className="field-hint">Nenhum serviço adicionado.</p>}</div></CardContent></Card><Card className="quote-summary"><CardHeader><CardTitle>Resumo do orçamento</CardTitle><p>{client || 'Sem identificação de cliente'}</p></CardHeader><CardContent><div className="summary-lines"><div><span>Subtotal</span><strong>{formatCurrency(subtotal)}</strong></div><div><span>Desconto</span><Input type="number" min="0" max="100" value={discount} onChange={(e) => setDiscount(Number(e.target.value))} /></div><div className="summary-total"><span>Total proposto</span><strong>{formatCurrency(total)}</strong></div></div><Button className="primary-button full-button" disabled={!items.length} onClick={() => onSave({ id: newId('quote'), clientName: client.trim(), items, discount: safeNumber(discount), total, createdAt: new Date().toISOString() })}><Check size={15} /> Salvar orçamento</Button><p className="field-hint">Salvo localmente e sem alterar os preços do catálogo.</p></CardContent></Card></div><div className="section-title-row"><div><p className="eyebrow">HISTÓRICO COMERCIAL</p><h2>Orçamentos salvos</h2></div></div><Card className="table-card"><Table><TableHeader><TableRow><TableHead>Cliente</TableHead><TableHead>Serviços</TableHead><TableHead>Desconto</TableHead><TableHead>Total</TableHead><TableHead>Data</TableHead></TableRow></TableHeader><TableBody>{quotes.slice(0, 10).map((quote) => <TableRow key={quote.id}><TableCell><strong>{quote.clientName || 'Sem identificação'}</strong></TableCell><TableCell>{quote.items.length}</TableCell><TableCell>{quote.discount}%</TableCell><TableCell><strong>{formatCurrency(quote.total)}</strong></TableCell><TableCell>{formatDate(quote.createdAt)}</TableCell></TableRow>)}</TableBody></Table>{!quotes.length && <Empty icon={<FileDown size={18} />} title="Nenhum orçamento salvo" description="Monte sua primeira proposta com os serviços cadastrados." />}</Card></>;
}

function SettingsView({ settings, onSave }: { settings: PricingSettings; onSave: (settings: PricingSettings) => void }) {
  const [draft, setDraft] = useState(settings);
  const branding = draft.branding;
  const updateBranding = (patch: Partial<BrandingSettings>) => setDraft({ ...draft, branding: { ...branding, ...patch } });
  return <><div className="page-heading"><div><p className="eyebrow">PERSONALIZAÇÃO E REGRAS</p><h1>Configurações</h1><p className="page-description">Ajuste nomes, logo, cores, tema e regras financeiras.</p></div></div><form className="settings-grid" onSubmit={(e) => { e.preventDefault(); onSave(normalizeSettings(draft)); }}><Card><CardHeader><CardTitle><UserRound size={16} /> Identidade</CardTitle><p>Personalize a apresentação do aplicativo.</p></CardHeader><CardContent><div className="branding-preview"><div className="brand-mark">{branding.logoSymbol || '✦'}</div><div><strong>{branding.appName || 'OdontoPrice'}</strong><span>{branding.clinicName || 'Sua clínica'}</span></div></div><div className="settings-fields"><Field label="Nome do aplicativo"><Input value={branding.appName} onChange={(e) => updateBranding({ appName: e.target.value })} /></Field><Field label="Nome da clínica"><Input value={branding.clinicName} onChange={(e) => updateBranding({ clinicName: e.target.value })} /></Field><Field label="Nome da profissional"><Input value={branding.dentistName} onChange={(e) => updateBranding({ dentistName: e.target.value })} /></Field><Field label="Texto do logo"><Input value={branding.logoText} maxLength={4} onChange={(e) => updateBranding({ logoText: e.target.value })} /></Field><Field label="Ícone/símbolo do logo"><Input value={branding.logoSymbol} maxLength={3} onChange={(e) => updateBranding({ logoSymbol: e.target.value })} /></Field><Field label="Tema"><select className="select-input" value={draft.theme} onChange={(e) => setDraft({ ...draft, theme: e.target.value === 'dark' ? 'dark' : 'light' })}><option value="light">Claro · rosa suave</option><option value="dark">Escuro</option></select></Field><Field label="Cor principal"><div className="color-field"><Input type="color" value={branding.primaryColor} onChange={(e) => updateBranding({ primaryColor: e.target.value })} /><code>{branding.primaryColor}</code></div></Field><Field label="Cor de destaque"><div className="color-field"><Input type="color" value={branding.accentColor} onChange={(e) => updateBranding({ accentColor: e.target.value })} /><code>{branding.accentColor}</code></div></Field></div></CardContent></Card><Card><CardHeader><CardTitle><CircleDollarSign size={16} /> Parâmetros financeiros</CardTitle><p>Aplicados automaticamente nos cálculos.</p></CardHeader><CardContent><div className="settings-fields"><Field label="Horas clínicas produtivas/mês"><Input type="number" min="1" value={draft.monthlyClinicalHours} onChange={(e) => setDraft({ ...draft, monthlyClinicalHours: Number(e.target.value) })} /></Field><Field label="Impostos"><Input type="number" min="0" step="0.01" value={draft.taxRate} onChange={(e) => setDraft({ ...draft, taxRate: Number(e.target.value) })} /></Field><Field label="Taxas de pagamento"><Input type="number" min="0" step="0.01" value={draft.paymentFeeRate} onChange={(e) => setDraft({ ...draft, paymentFeeRate: Number(e.target.value) })} /></Field><Field label="Margem padrão"><Input type="number" min="0" step="0.01" value={draft.defaultMargin} onChange={(e) => setDraft({ ...draft, defaultMargin: Number(e.target.value) })} /></Field></div><div className="hour-cost-callout"><span>Custos fixos ativos</span><strong>{formatCurrency(getMonthlyFixedCosts(draft))}</strong><small>Detalhamento disponível na aba Custos fixos.</small></div></CardContent></Card><div className="settings-save"><Button type="submit" className="primary-button"><Check size={15} /> Salvar configurações</Button><span><ShieldCheck size={13} /> Persistência local no navegador</span></div></form></>;
}

function HistoryView({ history }: { history: HistoryEntry[] }) {
  return <><div className="page-heading"><div><p className="eyebrow">RASTREABILIDADE</p><h1>Histórico de alterações</h1><p className="page-description">Mudanças de preços, cadastros e configurações.</p></div></div><Card className="history-card"><CardHeader><CardTitle>Atividade recente</CardTitle><p>Os registros permanecem neste dispositivo.</p></CardHeader><CardContent>{history.length ? <div className="timeline">{history.map((entry) => <div className="timeline-item" key={entry.id}><div className="timeline-icon"><Check size={12} /></div><div className="timeline-content"><strong>{entry.action}</strong><p>{entry.detail}</p><span>{formatDate(entry.createdAt)}</span></div></div>)}</div> : <Empty icon={<History size={18} />} title="Ainda não há alterações" description="O histórico aparecerá quando você cadastrar ou editar dados." />}</CardContent></Card></>;
}

export default function Home() {
  const [view, setView] = useState<View>('dashboard');
  const [procedures, setProcedures] = useState<Procedure[]>(DEFAULT_PROCEDURES);
  const [materials, setMaterials] = useState<Material[]>(DEFAULT_MATERIALS);
  const [settings, setSettings] = useState<PricingSettings>(DEFAULT_SETTINGS);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [menuOpen, setMenuOpen] = useState(false);
  const [materialModal, setMaterialModal] = useState<Material | 'new' | null>(null);
  const [procedureModal, setProcedureModal] = useState<Procedure | 'new' | null>(null);
  const [fixedModalMaterial, setFixedModalMaterial] = useState<Material | null>(null);
  const [toast, setToast] = useState('');
  const [mounted, setMounted] = useState(false);
  useEffect(() => { queueMicrotask(() => { setProcedures(readStorage(STORAGE.procedures, DEFAULT_PROCEDURES).map(normalizeProcedure)); setMaterials(readStorage(STORAGE.materials, DEFAULT_MATERIALS).map(normalizeMaterial)); setSettings(normalizeSettings(readStorage(STORAGE.settings, DEFAULT_SETTINGS))); setHistory(readStorage(STORAGE.history, [])); setQuotes(readStorage(STORAGE.quotes, [])); setMounted(true); }); }, []);
  useEffect(() => { if (!mounted) return; localStorage.setItem(STORAGE.procedures, JSON.stringify(procedures)); localStorage.setItem(STORAGE.materials, JSON.stringify(materials)); localStorage.setItem(STORAGE.settings, JSON.stringify(settings)); localStorage.setItem(STORAGE.history, JSON.stringify(history)); localStorage.setItem(STORAGE.quotes, JSON.stringify(quotes)); }, [mounted, procedures, materials, settings, history, quotes]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 2600); return () => window.clearTimeout(timer); }, [toast]);
  const addHistory = (action: string, detail: string) => setHistory((current) => [{ id: newId('history'), action, detail, createdAt: new Date().toISOString() }, ...current].slice(0, 100));
  const saveMaterial = (material: Material) => { const old = materials.find((item) => item.id === material.id); const id = old ? material.id : newId('material'); const changed = Boolean(old && old.packagePrice !== material.packagePrice); const now = new Date().toISOString(); const next = { ...material, id, baseUnitCost: material.packagePrice / material.packageQuantity, updatedAt: changed ? now : material.updatedAt, priceHistory: changed && old ? [...old.priceHistory, { id: newId('price'), materialId: id, previousPackagePrice: old.packagePrice, newPackagePrice: material.packagePrice, updatedAt: now, supplier: material.supplier || old.supplier || undefined }] : material.priceHistory }; setMaterials((current) => old ? current.map((item) => item.id === id ? next : item) : [...current, next]); addHistory(old ? changed ? 'Preço de material atualizado' : 'Material atualizado' : 'Material criado', material.name); setMaterialModal(null); setToast('Material salvo com sucesso'); };
  const saveProcedure = (procedure: Procedure) => { const exists = procedures.some((item) => item.id === procedure.id); setProcedures((current) => exists ? current.map((item) => item.id === procedure.id ? procedure : item) : [...current, procedure]); addHistory(exists ? 'Procedimento atualizado' : 'Procedimento criado', procedure.name); setProcedureModal(null); setToast('Procedimento salvo com sucesso'); };
  const saveSettings = (next: PricingSettings) => { setSettings(normalizeSettings(next)); addHistory('Configurações atualizadas', 'Identidade, tema e regras financeiras'); setToast('Configurações salvas'); };
  const go = (next: View) => { setView(next); setMenuOpen(false); };
  const branding = settings.branding || DEFAULT_BRANDING;
  const groups = [{ label: 'PRINCIPAL', items: [{ id: 'dashboard' as View, label: 'Visão geral' }, { id: 'simulator' as View, label: 'Simulador' }, { id: 'budget' as View, label: 'Orçamentos' }] }, { label: 'GESTÃO', items: [{ id: 'procedures' as View, label: 'Procedimentos' }, { id: 'materials' as View, label: 'Materiais e insumos' }, { id: 'fixed-costs' as View, label: 'Custos fixos' }] }, { label: 'SISTEMA', items: [{ id: 'settings' as View, label: 'Configurações' }, { id: 'history' as View, label: 'Histórico' }] }];
  const content = view === 'dashboard' ? <Dashboard procedures={procedures} materials={materials} settings={settings} navigate={go} /> : view === 'simulator' ? <Simulator procedures={procedures} materials={materials} settings={settings} /> : view === 'procedures' ? <Procedures procedures={procedures} materials={materials} settings={settings} onNew={() => setProcedureModal('new')} onEdit={setProcedureModal} /> : view === 'materials' ? <Materials materials={materials} onNew={() => setMaterialModal('new')} onEdit={setMaterialModal} onInactivate={setFixedModalMaterial} onActivate={(material) => { setMaterials((current) => current.map((item) => item.id === material.id ? { ...item, active: true } : item)); addHistory('Material ativado', material.name); }} /> : view === 'fixed-costs' ? <FixedCosts settings={settings} onSave={setSettings} onHistory={addHistory} /> : view === 'budget' ? <Budget procedures={procedures} materials={materials} settings={settings} quotes={quotes} onSave={(quote) => { setQuotes((current) => [quote, ...current]); addHistory('Orçamento criado', quote.clientName || 'Sem identificação'); setToast('Orçamento salvo'); }} /> : view === 'settings' ? <SettingsView settings={settings} onSave={saveSettings} /> : <HistoryView history={history} />;
  return <div className={'app-shell ' + (settings.theme === 'dark' ? 'theme-dark' : '')} style={{ '--brand-primary': branding.primaryColor, '--brand-accent': branding.accentColor } as CSSProperties}><aside className={'sidebar ' + (menuOpen ? 'sidebar-open' : '')}><div className="brand"><div className="brand-mark">{branding.logoSymbol || '✦'}</div><div><strong>{branding.appName || 'OdontoPrice'}</strong><small>PRECIFICAÇÃO ODONTOLÓGICA</small></div></div><div className="clinic-switcher"><div className="clinic-avatar">{branding.logoText || 'OP'}</div><div><strong>{branding.clinicName || 'Sua clínica'}</strong><span>{branding.dentistName || 'Profissional'}</span></div><ChevronRight size={14} className="muted-icon" /></div>{groups.map((group) => <div key={group.label}><p className={'menu-label ' + (group.label !== 'PRINCIPAL' ? 'secondary-label' : '')}>{group.label}</p><nav className="main-nav">{group.items.map((item) => <button key={item.id} className={view === item.id ? 'active' : ''} onClick={() => go(item.id)}><Icon name={item.id} />{item.label}{item.id === 'history' && history.length > 0 && <span className="history-count">{history.length}</span>}</button>)}</nav></div>)}<div className="sidebar-footer"><div className="secure-dot"><ShieldCheck size={14} /></div><div><strong>Dados locais</strong><span>Persistência segura</span></div></div></aside><main className="main-area"><header className="topbar"><div className="mobile-brand"><button className="icon-button" onClick={() => setMenuOpen(!menuOpen)} aria-label="Abrir menu" title="Abrir menu"><Menu size={20} /></button><div className="brand-mark">{branding.logoSymbol || '✦'}</div><strong>{branding.appName || 'OdontoPrice'}</strong></div><div className="topbar-context"><span>PAINEL DE CONTROLE</span><strong>{branding.clinicName || 'Sua clínica'} <span className="wave">·</span> {branding.dentistName || 'Profissional'}</strong></div><div className="topbar-actions"><Button variant="ghost" className="export-action" onClick={() => window.print()}><Download size={14} /> Exportar / PDF</Button><Button variant="ghost" size="icon" onClick={() => saveSettings({ ...settings, theme: settings.theme === 'dark' ? 'light' : 'dark' })} aria-label={settings.theme === 'dark' ? 'Ativar tema claro' : 'Ativar tema escuro'} title="Alternar tema">{settings.theme === 'dark' ? <Sun size={16} /> : <Moon size={16} />}</Button><div className="user-avatar">{(branding.dentistName || 'FT').split(' ').filter(Boolean).slice(0, 2).map((item) => item[0]).join('').toUpperCase()}</div></div></header><section className="content-wrap">{content}</section></main>{procedureModal && <ProcedureForm key={procedureModal === 'new' ? 'new' : procedureModal.id} value={procedureModal} materials={materials} onClose={() => setProcedureModal(null)} onSave={saveProcedure} />}{materialModal && <MaterialForm key={materialModal === 'new' ? 'new' : materialModal.id} value={materialModal} onClose={() => setMaterialModal(null)} onSave={saveMaterial} />}{fixedModalMaterial && <Modal title="Inativar material?" description="O registro será preservado para manter histórico e integridade." onClose={() => setFixedModalMaterial(null)}><div className="confirm-content"><div className="confirm-icon"><Ban size={19} /></div><p>O material <strong>{fixedModalMaterial.name}</strong> ficará inativo e não aparecerá para novos procedimentos. Vínculos existentes continuam funcionando.</p><div className="modal-actions"><Button variant="outline" onClick={() => setFixedModalMaterial(null)}>Cancelar</Button><Button className="danger-button" onClick={() => { const material = fixedModalMaterial; setMaterials((current) => current.map((item) => item.id === material.id ? { ...item, active: false } : item)); addHistory('Material inativado', material.name); setFixedModalMaterial(null); setToast('Material inativado sem apagar o histórico'); }}><Ban size={15} /> Inativar material</Button></div></div></Modal>}{toast && <output className="toast"><Check size={14} /> {toast}</output>}</div>;
}

